import {mountCrucibleController} from './crucible-controller.js';
import {scopeMarkup} from './card-markup.js';
import {combustionArtwork} from './combustion-workbench.js';
import {createCombustionAtmosphere} from './combustion-atmosphere.js';

export const redoxCases={
 alone:{name:'只有氧化銅',before:'黑色 CuO',after:'仍是黑色 CuO',formula:'CuO 單獨加熱：本例未取回銅',text:'只有加熱，沒有看見紅棕色銅。加入碳再比較。',result:'#252b2b'},
 carbon:{name:'氧化銅 ＋ 碳',before:'黑色 CuO ＋ 黑色碳粉',after:'可見紅棕色銅',formula:'2CuO + C → 2Cu + CO₂',text:'氧離開 CuO，進入碳的氧化物；金屬銅被留了下來。CO₂ 無色。',result:'#bb6c47'},
 ZnCu:{name:'鋅 ＋ 氧化銅',before:'灰色鋅粉 ＋ 黑色 CuO',after:'紅棕色銅 ＋ 白色 ZnO',formula:'Zn + CuO → ZnO + Cu',text:'鋅得到氧，CuO 失去氧。冷卻後 ZnO 呈白色，銅呈紅棕色。',result:'#bb6c47'},
 CuZn:{name:'銅 ＋ 氧化鋅',before:'紅棕色銅 ＋ 白色 ZnO',after:'冷卻後無淨奪氧反應',formula:'Cu + ZnO：本例未反向奪氧',text:'交換角色後，銅無法從 ZnO 奪氧；原來的銅與 ZnO 仍留在坩堝裡。',result:'#ecebde'}
};

export function crucibleArt(key,finished=false,cool=true,{progress=false}={}){
 const powder=(done)=>{
  const white=(key==='ZnCu'||key==='CuZn')&&done,base=key==='CuZn'||white?(cool?'#e9e7d7':'#d7bd46'):done&&key==='carbon'?'#773c26':'#252a28';
  const grains=Array.from({length:92},(_,i)=>{const a=i*2.39996,r=Math.sqrt((i+.5)/92),x=80+Math.cos(a)*r*52,y=44+Math.sin(a)*r*12;const copper=key==='CuZn'?i%3===0:done&&key==='carbon'?i%4!==0:done&&key==='ZnCu'?i%2===0:false;const zinc=!done&&key==='ZnCu'&&i%3===0;return `<path d="M${x.toFixed(2)} ${y.toFixed(2)}l${(1.1+i%3*.4).toFixed(1)} -1.2 1.8 .5 -.8 1.3 -1.9 .2Z" fill="${copper?'url(#copper-grain)':zinc?'#a5ada9':base}" stroke="${copper?'#f0bc8455':'#ffffff15'}" stroke-width=".24"/>`;}).join('');
  return `<path d="M26 46Q28 32 80 30Q129 32 135 46Q122 59 80 59Q41 58 26 46Z" fill="${base}"/><path d="M26 46Q28 32 80 30Q129 32 135 46Q122 59 80 59Q41 58 26 46Z" fill="url(#powder-grain)"/>${grains}`;
 };
 return `<svg viewBox="0 0 160 100" aria-hidden="true"><defs><linearGradient id="porcelain"><stop stop-color="#8e9d96"/><stop offset=".2" stop-color="#e8ece2"/><stop offset=".45" stop-color="#faf9ed"/><stop offset=".8" stop-color="#b8c5bb"/><stop offset="1" stop-color="#647e74"/></linearGradient><radialGradient id="cup-inside"><stop stop-color="#7b857c"/><stop offset=".7" stop-color="#bbc2b3"/><stop offset="1" stop-color="#eaf0e4"/></radialGradient><linearGradient id="copper-grain" x2=".5" y2="1"><stop stop-color="#f2c28c"/><stop offset=".25" stop-color="#cb8654"/><stop offset=".55" stop-color="#8d4b2f"/><stop offset=".8" stop-color="#e6a36a"/><stop offset="1" stop-color="#9c5839"/></linearGradient><pattern id="powder-grain" width="3.2" height="2.7" patternUnits="userSpaceOnUse"><circle cx=".5" cy=".6" r=".35" fill="#fff" opacity=".18"/><circle cx="2" cy="2" r=".5" fill="#000" opacity=".24"/><path d="M1 1.8l.6 -.4" stroke="#ded9ba" stroke-opacity=".2" stroke-width=".3"/></pattern><radialGradient id="hot-cup"><stop stop-color="#ffe2a3" stop-opacity=".5"/><stop offset="1" stop-color="#d95b19" stop-opacity="0"/></radialGradient></defs><ellipse cx="80" cy="86" rx="58" ry="8" fill="#1c3938" opacity=".15"/><path d="M15 40Q18 85 80 87Q142 85 145 40Z" fill="url(#porcelain)" stroke="#8d9f98"/><path d="M30 53Q41 76 76 78" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="2"/><path d="M122 59Q110 76 91 79" fill="none" stroke="#748b7b" stroke-opacity=".3"/><ellipse cx="80" cy="40" rx="65" ry="22" fill="url(#cup-inside)" stroke="#e7eee4" stroke-width="3"/>${progress?`<g class="redox-powder-before">${powder(false)}</g><g class="redox-powder-after">${powder(true)}</g>`:powder(finished)}<path d="M16 41Q79 70 144 41" fill="none" stroke="#c7d1c6" stroke-width="2"/><path d="M21 37Q34 23 68 21" stroke="#fffef4" stroke-opacity=".8" stroke-width="1.3" fill="none"/><ellipse class="redox-hot-glow" cx="80" cy="63" rx="60" ry="24" fill="url(#hot-cup)"/></svg>`;
}

export function mountRedox(root,c,{s,has,record,notice,onCleanup,setCase}){
 const key=s.selected,d=redoxCases[key],loaded=!!s.autoLoad,position=s.spoonOrigin||[320,229];s.autoLoad=false;s.spoonOrigin=null;
 const background=combustionArtwork('Cu','load',true).replace('class="combustion-art"','class="redox-art"').replace('aria-label="酒精燈與金屬燃燒匙"','aria-label="瓷坩堝、三腳架與酒精燈的還原實驗台"');
 const rack=Object.entries(redoxCases).map(([k,v])=>`<div class="redox-rack-sample ${key===k&&loaded?'selected':''}" data-redox-sample="${k}" aria-label="${v.name}樣本">${scopeMarkup(crucibleArt(k),'rack-'+k)}<b>${v.name}</b><small>${has(k)?'✓ 已觀察':'拖到下方加熱架'}</small></div>`).join('');
 root.innerHTML=scopeMarkup(`<button class="studio-enter" data-enter-redox>進入還原實驗台，查看樣本與加熱架 ↘</button><div class="redox-workshop" tabindex="-1"><div class="redox-sample-rack"><div class="redox-rack-heading"><b>鐵匠的還原樣本架</b><span>取一份樣本 → 放上加熱架 → 比較前後</span></div><div class="redox-rack-rail">${rack}</div></div><div class="redox-scene" data-phase="ready">${background}<svg class="redox-art" viewBox="0 0 760 430" style="position:absolute;inset:0" aria-hidden="true"><defs><linearGradient id="tripod-steel"><stop stop-color="#2f4951"/><stop offset=".4" stop-color="#d9e2de"/><stop offset=".58" stop-color="#5d747d"/><stop offset="1" stop-color="#9aacac"/></linearGradient><pattern id="wire-mesh" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 0H5V5" fill="none" stroke="#6b7d7c" stroke-width=".6"/></pattern></defs><path d="M250 229L229 360M389 229L410 360M320 236L326 365" stroke="url(#tripod-steel)" stroke-width="5"/><ellipse cx="320" cy="229" rx="72" ry="15" fill="url(#wire-mesh)" stroke="#566f72" stroke-width="4"/></svg><div class="redox-load-target drop-target" data-redox-load-target ${loaded?'hidden':''}><span>① 把架上樣本拖到這裡</span></div><div class="redox-heat-target drop-target" data-redox-target ${loaded?'':'hidden'}><span>② 坩堝放上加熱架 ↓</span></div>${loaded?`<div class="redox-cup" data-redox-cup aria-label="${d.name}的瓷坩堝">${crucibleArt(key)}<span>${d.before}</span></div>`:''}<aside class="redox-detail"><b>${loaded?'加熱前 · 先看清楚':'只有熱，還是需要幫手？'}</b>${loaded?scopeMarkup(crucibleArt(key),'initial-inset')+'<p>'+d.before+'</p>':'<p>先取「只有氧化銅」，再取「氧化銅＋碳」。</p>'}<p>${loaded?'將樣本放上加熱架；完成後直接比較加熱前後。':'兩份同樣加熱，看看哪份能留下紅棕色銅。'}</p><p class="redox-formula">線索：金屬有沒有回來？</p><div class="redox-heat-meter" aria-hidden="true"></div></aside></div><p class="redox-phase" aria-live="polite">${loaded?'樣本已放好。把瓷坩堝拖上加熱架。':'從上方樣本架取一份，拖到下方加熱架。'}</p><button class="redox-replay" hidden data-redox-replay>取一份相同樣本，再觀察</button></div>`,'redox-workshop-'+key);
 const scene=root.querySelector('.redox-scene');
 const atmosphere=createCombustionAtmosphere();if(atmosphere){scene.append(atmosphere.canvas);atmosphere.update({key:'Cu',stage:'load',isMetal:true,heater:1});scene.classList.add('atmosphere-ready');onCleanup(()=>atmosphere.dispose());}
 mountCrucibleController(root,{key,d,loaded,position,crucibleArt,record,notice,onCleanup,setCase,onCooled:()=>atmosphere?.update({key:'Cu',stage:'done',isMetal:true,heater:0})});
 root.querySelector('[data-redox-replay]').addEventListener('click',()=>{setCase(key,true);const bench=root.querySelector('.redox-workshop');bench.scrollIntoView({block:'start',behavior:'instant'});bench.focus({preventScroll:true});});
 root.querySelector('[data-enter-redox]').addEventListener('click',()=>{const bench=root.querySelector('.redox-workshop');bench.scrollIntoView({block:'start',behavior:'instant'});bench.focus({preventScroll:true});});
}
